"""Normalize release records and replay identity at the input boundary."""


class JournalError(ValueError):
    pass


def _read_id_list(value):
    """Return a dependency/id collection as a list of strings; booleans are not strings."""
    if not isinstance(value, list):
        raise JournalError("invalid-change")
    for name in value:
