        targets = row["depends_on"]
        for target in targets:
            if target not in dependents:
                raise JournalError("unknown-dependency")
            dependents[target].append(row["id"])
        counts[row["id"]] = len(set(targets))
    ready = [name for name, count in counts.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        name = heapq.heappop(ready)
        order.append(name)
