        unknown = applied - by_id.keys()
        if unknown:
            raise JournalError("unknown-dependency")
        order = topo_order(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    # Replay is decided on the full deterministic order before budget accounting:
    # already applied entries satisfy dependencies and never spend new budget.
    if action == "rollback":
        actions = [name for name in reversed(order) if name in applied]
    else:
        actions = [name for name in order if name not in applied]
    units = sum(by_id[name]["units"] for name in actions)
