"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes, read_retain
from policy import PolicyError, check_budget, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def topo_order(changes):
    """Return the unique deterministic topological order of the whole graph.

    Dependency direction: an edge b -> a means "a depends_on b", so b must be
    emitted first. Among all changes whose dependencies are already emitted we
    always pick the lexicographically smallest id (a min-heap), which makes the
    order a pure function of the change set and therefore reproducible for
    rollback (including its reverse order and G2's retained subset of it).
    Cycles anywhere in the graph (applied or not) fail closed.
    """
    counts = {}
    dependents = {row["id"]: [] for row in changes}
    for row in changes:
        targets = row["depends_on"]
        for target in targets:
            if target not in dependents:
                raise JournalError("unknown-dependency")
            dependents[target].append(row["id"])
        counts[row["id"]] = len(set(targets))
    ready = [name for name, count in counts.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        name = heapq.heappop(ready)
        order.append(name)
        for dependent in dependents[name]:
            counts[dependent] -= 1
            if counts[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(changes):
        raise JournalError("dependency-cycle")
    return order


def read_request(request):
    return read_changes(request.get("changes")), read_applied(request)


def required_retained(by_id, applied, retain):
    """Return the applied changes that must stay during a rollback.

    A retained change keeps its transitive dependencies, because rolling a
    dependency back under a remaining dependent would leave an inconsistent
    release. The traversal follows `depends_on` (the direction that must come
    first) and only includes dependencies that are applied: an unapplied
    dependency is not present to remove, and its own dependencies would not be
    reachable through a real rollback either.
    """
    kept = set()
    pending = list(retain)
    while pending:
        name = pending.pop()
        if name in kept:
            continue
        kept.add(name)
        for target in by_id[name]["depends_on"]:
            if target in applied and target not in kept:
                pending.append(target)
    return kept


def retained_rollback(by_id, applied, retain, order):
    """Emit applied changes in reverse deterministic order, minus retained ones.

    The order is the reverse of the full topological order (not of a
    re-sorted subset), so a retained change never reorders its siblings and the
    remaining actions keep their G1 positions.
    """
    kept = required_retained(by_id, applied, retain)
    return [name for name in reversed(order) if name in applied and name not in kept]


def plan(request):
    # Fail closed on a non-object request before policy touches it: policy reads
    # .get() and a JSON array/scalar would otherwise crash the process instead of
    # returning the documented `invalid-request` result.
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget, action = limit_for(request)
