        return failure(str(exc))
    # G2 freeze: production is decided on transport fields alone, before the
    # journal or graph is read, so a malformed `changes`/`applied` graph cannot
    # swap the frozen error for a graph error. Nothing is emitted either way.
    if action is None:
        return failure("production-frozen")
    try:
        changes, applied = read_request(request)
        # `retain` is a rollback-only field. On a plan it must not silently shape
        # anything, so any caller sending it gets `invalid-retain` with no actions;
        # on a rollback only the shape is validated here (ids are checked below).
        retain = read_retain(request)
        if action != "rollback" and retain:
            raise JournalError("invalid-retain")
        by_id = {row["id"]: row for row in changes}
        unknown = applied - by_id.keys()
        if unknown:
            raise JournalError("unknown-dependency")
        # A retained change must already be applied to be "kept"; anything else
        # is an unrepresentable rollback request and fails closed.
        if not retain <= applied:
            raise JournalError("invalid-retain")
        order = topo_order(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    # Replay is decided on the full deterministic order before budget accounting:
    # already applied entries satisfy dependencies and never spend new budget.
    if action == "rollback":
        actions = retained_rollback(by_id, applied, retain, order)
    else:
        actions = [name for name in order if name not in applied]
    units = sum(by_id[name]["units"] for name in actions)
    try:
        check_budget(action, budget, units)
    except PolicyError as exc:
        return failure(str(exc))
    return {"status": "ok", "actions": actions, "units": units}

