"""Normalize release records at the input boundary.

This module owns change-record shape validation, replay identity and
deduplication. It never decides execution order and never adds up units;
planner.py does both after calling in here.
"""


class JournalError(ValueError):
    pass


def _id_list(value):
    if not isinstance(value, list):
        raise JournalError("invalid-change")
    for item in value:
        if not isinstance(item, str) or not item:
            raise JournalError("invalid-change")
    return value


def read_changes(records):
    """Validate ``changes`` and collapse identical duplicate records.

    Replay identity is ``(id, component, units, frozenset(depends_on))``:
    the dependency comparison is a set, so two records listing the same ids
    in a different order are the same change. Deduplication has to happen
    here, before planner builds the graph and sums budget, otherwise a
    repeated record would count twice.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    seen = {}
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        depends_on = _id_list(row.get("depends_on", []))
        key = (row["id"], row["component"], row["units"], frozenset(depends_on))
        known = seen.get(row["id"])
        if known is None:
            seen[row["id"]] = key
        elif known != key:
            # Same id with a different replay key is an ambiguous journal
            # entry: fail closed rather than pick one of the two definitions.
            raise JournalError("conflicting-change")
        else:
            continue  # identical duplicate: keep the first occurrence only
        changes.append({
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": list(depends_on),
        })
    return changes


def read_applied(raw, known_ids):
    """Validate the persisted journal of applied change IDs.

    The journal is caller-supplied state, so anything that is not a list of
    nonempty strings is ``invalid-change``; ids that no supplied change
    defines are ``unknown-dependency`` because their position in the graph
    cannot be established. Duplicates are folded into a set.
    """
    if raw is None:
        return set()
    if not isinstance(raw, list):
        raise JournalError("invalid-change")
    applied = set()
    for item in raw:
        if not isinstance(item, str) or not item:
            raise JournalError("invalid-change")
        if item not in known_ids:
            raise JournalError("unknown-dependency")
        applied.add(item)
    return applied

