"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    # Fail-closed envelope: a rejected request never leaks partial actions or
    # a nonzero unit count, so the caller cannot mistake it for a plan.
    return {"status": "error", "error": code, "actions": [], "units": 0}


def deterministic_order(changes):
    """Topological order of all changes, ready set broken by smallest id.

    Graph direction: an edge goes from a change to the ids it depends on,
    and a change only becomes eligible once every dependency has been
    emitted -- dependencies always execute first. The cycle check runs over
    the whole graph, including changes already applied, so a broken journal
    is rejected even when the cycle never reaches the emitted actions.
    """
    ids = {row["id"] for row in changes}
    targets = {}
    dependents = {row["id"]: [] for row in changes}
    for row in changes:
        for dep in row["depends_on"]:
            if dep not in ids:
                raise JournalError("unknown-dependency")
        unique = sorted(set(row["depends_on"]))
        targets[row["id"]] = unique
        for dep in unique:
            dependents[dep].append(row["id"])

    ready = [cid for cid, deps in targets.items() if not deps]
    heapq.heapify(ready)
    remaining = {cid: len(deps) for cid, deps in targets.items()}
    order = []
    while ready:
        cid = heapq.heappop(ready)
        order.append(cid)
        for dependent in dependents[cid]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(targets):
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        action, budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied"), {row["id"] for row in changes})
        full_order = deterministic_order(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    units_by_id = {row["id"]: row["units"] for row in changes}
