"""Normalize release records at the input boundary: shape, replay identity, graph targets."""


class JournalError(ValueError):
    pass


def read_changes(records):
    """Validate `changes` and collapse replay duplicates.

    Returns [{"id", "component", "units", "depends_on"}] in first-seen order, with
    `depends_on` normalized to a sorted list of distinct IDs.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    ordered = []
    seen = {}
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        raw_deps = row.get("depends_on", [])
        if not isinstance(raw_deps, list):
            raise JournalError("invalid-change")
        for dep in raw_deps:
            if not isinstance(dep, str) or not dep:
                raise JournalError("invalid-change")
        # Replay identity is id + component + units + the *set* of dependencies. Repeating a
        # dependency never changes the graph, so it is not an identity difference; sorting plus
        # distinct-normalizing here makes an exact replay collapse no matter how its list is
        # ordered, while a genuinely different payload stays different and fails below.
        change = {"id": row["id"], "component": row["component"],
                  "units": row["units"], "depends_on": sorted(set(raw_deps))}
        prior = seen.get(change["id"])
        if prior is None:
            seen[change["id"]] = change
            ordered.append(change)
        elif prior != change:
            # Same id, different payload: fail closed instead of choosing a winner, so units are
            # never silently double-counted or silently dropped.
            raise JournalError("conflicting-change")
    return ordered


def read_applied(raw, changes):
    """Validate the caller-supplied release journal and resolve it against known change IDs.

