"""Compose policy and journal data into a topological plan or rollback."""
import heapq

from journal import JournalError, read_applied, read_changes, read_retain
from policy import PolicyError, environment, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def order_changes(changes):
    """Return the full deterministic topological order of all change IDs.

    Edges point from a change to its dependencies (a depends on b  =>  a -> b), so a change
    becomes eligible only once every dependency has been emitted. Among the changes that are
    eligible at the same time the lexicographically smallest ID wins, which makes the order a
    total, reproducible function of the input set.
    """
    lookup = {change["id"]: change for change in changes}
    pending = {}
    dependents = {change["id"]: [] for change in changes}
    for change in changes:
        missing = [dep for dep in change["depends_on"] if dep not in lookup]
        if missing:
            # A dependency that names nothing in this request can never be satisfied.
            raise JournalError("unknown-dependency")
        pending[change["id"]] = len(change["depends_on"])
        for dep in change["depends_on"]:
            dependents[dep].append(change["id"])
    ready = [change_id for change_id, count in pending.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(current)
        for dependent in dependents[current]:
            pending[dependent] -= 1
            if pending[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(changes):
        # Graph validation completes before any selection, so a rejected request emits nothing.
        raise JournalError("dependency-cycle")
    return order


def retained_ids(retain, changes, applied):
    """Return retain plus every applied change those retained changes transitively need.

    A retained change stays applied, so whatever it depends on must stay too -- otherwise the
    rollback would leave a running change without its dependencies. Only *applied* dependencies
    are pulled in: an unapplied dependency is never rolled back in the first place, so counting
    it would enlarge the retained set for nothing.
    """
    deps = {change["id"]: change["depends_on"] for change in changes}
    keep = set(retain)
    stack = list(retain)
    while stack:
        for dep in deps[stack.pop()]:
            if dep in applied and dep not in keep:
                keep.add(dep)
                stack.append(dep)
    return keep


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Environment is decided first so a frozen production request is refused before any
        # graph or change validation can run, whatever those inputs look like.
        environment(request)
        action, budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied"), changes)
        retain = read_retain(request.get("retain"), applied) if action == "rollback" else set()
        order = order_changes(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units_by_id = {change["id"]: change["units"] for change in changes}
    if action == "rollback":
        # Rollback walks the *full* order backwards -- not the order of the applied subset -- so
        # applied changes come out in the exact reverse of the order that would have applied them.
        # Retained changes and their applied dependencies are the only ones held back; the rest
        # keep that order. The budget field was validated above but by contract does not cap it.
        keep = retained_ids(retain, changes, applied)
        actions = [change_id for change_id in reversed(order)
                   if change_id in applied and change_id not in keep]
    else:
        # Replay runs before accounting: applied changes still pin dependencies in the order but
        # are filtered out here and so contribute neither actions nor units.
        actions = [change_id for change_id in order if change_id not in applied]
    units = sum(units_by_id[change_id] for change_id in actions)
    if action == "plan" and units > budget:
        # Budget is measured on the deduplicated, replayed set, never on the raw record list.
        # `budget` already carries the G2 staging cap, so a permissive request cannot exceed it.
        return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": units}

